import {center,ORDER,CELL_ARCMIN,parseSky} from './sky-model.js';
import {parseSpectralImage,createSkyGrid,alignImage,drawAligned,sharedStretch} from './science/spectral.js';
import {processDisplay,groupVisits} from './cell-processing.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=day=>new Date(day+'T12:00:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
export const isCellView=()=>new URLSearchParams(location.search).get('view')==='cell'&&parseSky(location.search)?.order===ORDER;
export function cellMarkup(){const selection=parseSky(location.search),p=center(selection.id);return `<main id="main" class="cell-workspace" data-cell>
<section class="cell-image-area" aria-label="SPHEREx observation image"><div class="cell-image-bar"><a href="/explore/?hpx=${selection.id}&order=9" class="cell-back">← Sky atlas</a><span>SPHEREx <b>LEVEL 2</b></span><button id="cell-original" aria-pressed="false">View original</button></div>
<div class="cell-stage"><canvas id="cell-canvas" aria-label="Selected SPHEREx infrared observation" hidden></canvas><div class="cell-image-message" role="status"><span class="cell-spinner"></span><strong id="cell-message">Finding observations…</strong><p id="cell-message-detail">Searching NASA/IPAC for this patch of sky.</p><button id="cell-retry" hidden>Retry this date</button><button id="cell-nearest" hidden>Show nearest wavelength</button></div><div class="cell-compass" hidden>N ↑<br>E ←</div><div class="cell-image-caption" id="cell-caption"></div></div>
<div class="cell-image-footer"><output id="cell-pixel">Move across the image to inspect a pixel</output><label>Zoom <input id="cell-zoom" type="range" min="1" max="4" step=".25" value="1" aria-label="Image zoom"></label><button id="cell-fit">Fit</button></div></section>
<aside class="cell-rail"><div class="eyebrow">Observation workspace</div><h1>Cell ${selection.id}</h1><p class="cell-coordinate">RA ${p.ra.toFixed(5)}°<br>Dec ${p.dec.toFixed(5)}°</p><div class="cell-target"><span>Target</span><strong>Selected sky cell</strong><small>${CELL_ARCMIN.toFixed(2)}′ cell · 12′ context field</small></div>
<label class="cell-field">Wavelength target <select id="cell-wave" aria-label="Wavelength target" disabled><option>Loading wavelengths…</option></select></label><label class="cell-field">Wavelength window <select id="cell-tolerance" aria-label="Wavelength window"><option value=".04">±0.04 µm · narrow</option><option value=".08" selected>±0.08 µm · standard</option><option value=".16">±0.16 µm · wider</option></select></label>
<div class="cell-tools"><h2>Image cleanup</h2><label class="cell-toggle"><span>Quality mask<small>Hide flagged detector pixels</small></span><input type="checkbox" id="cell-quality" checked></label><label class="cell-toggle"><span>Remove sky background<small>Subtract the zodiacal-light model</small></span><input type="checkbox" id="cell-background" checked></label><label class="cell-field">Noise reduction <select id="cell-noise"><option value="0">Off</option><option value="1">Gentle</option><option value="2" selected>Strong · preserve edges</option></select></label><label class="cell-toggle"><span>Interpolate pixels<small>Smooth the enlarged display</small></span><input type="checkbox" id="cell-interpolate" checked></label><label class="cell-toggle"><span>Isolate target band<small>Hide pixels outside the wavelength window</small></span><input type="checkbox" id="cell-band-mask"></label><label class="cell-toggle"><span>Repair isolated gaps<small>Estimate single missing pixels</small></span><input type="checkbox" id="cell-repair"></label><label class="cell-field">Contrast <input id="cell-contrast" type="range" min=".4" max="2.5" step=".05" value="1.15"></label></div>
<details class="cell-provenance"><summary>Observation details</summary><div id="cell-details">Select a date to inspect its source exposure.</div><p>The image is displayed in grayscale. Wavelength varies across the field. Cleanup changes the display. Interpolation and gap repair add no new measurements. Contrast adjusts per exposure, so use the FITS data to compare brightness.</p><a href="https://caltech-ipac.github.io/irsa-tutorials/spherex-intro/" target="_blank" rel="noreferrer">About SPHEREx image data ↗</a></details></aside>
<section class="cell-timeline" aria-label="SPHEREx observation timeline"><div class="cell-timeline-heading"><div><span class="eyebrow">SPHEREx timeline · UTC</span><strong id="cell-date">Searching archive</strong></div><div class="cell-timeline-controls"><button id="cell-prev" aria-label="Previous observation date" disabled>←</button><button id="cell-play" disabled>Play</button><button id="cell-next" aria-label="Next observation date" disabled>→</button></div><span id="cell-count" role="status">Dated exposures will appear here</span></div><div class="cell-date-strip" id="cell-dates"></div><p class="cell-timeline-note">Each date opens a real exposure near the wavelength target. Dates are spaced evenly; gaps in the survey are not filled.</p></section></main>`;}
export function mountCell(){
 const root=document.querySelector('[data-cell]'),q=s=>root.querySelector(s),selection=parseSky(location.search),p=center(selection.id);
 let dead=false,searchController,frameController,requestId=0,visits=[],index=0,metadata,channel=62,wavelength=3.293,tolerance=.08,current=null,original=false,playing=false,playTimer,closest=null;
 const cache=new Map(),grid=createSkyGrid(p.ra,p.dec,.2),message=q('.cell-image-message'),canvas=q('#cell-canvas');
 const parameters=()=>new URLSearchParams({ra:p.ra,dec:p.dec,size:.2,wavelength,tolerance});
 function status(title,detail='',busy=false){message.hidden=false;q('#cell-message').textContent=title;q('#cell-message-detail').textContent=detail;q('.cell-spinner').hidden=!busy;}
 function clearImage(){current=null;closest=null;canvas.hidden=true;q('.cell-compass').hidden=true;q('#cell-caption').textContent='';q('#cell-details').textContent='No exposure displayed.';q('#cell-pixel').textContent='Move across the image to inspect a pixel';q('#cell-retry').hidden=true;q('#cell-nearest').hidden=true;}
 function stop(){playing=false;clearTimeout(playTimer);q('#cell-play').textContent='Play';}
 function renderTimeline(){
  q('#cell-dates').innerHTML=visits.map((v,i)=>`<button data-visit="${i}" class="cell-date ${i===index?'selected':''} ${v.status}" aria-pressed="${i===index}"><span>${new Date(v.day+'T12:00:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',timeZone:'UTC'})}</span><small>${v.day.slice(0,4)} · ${v.observations.length} ${v.observations.length===1?'exposure':'exposures'}</small><i></i></button>`).join('');
  q('#cell-date').textContent=visits[index]?dateLabel(visits[index].day):'No observations';q('#cell-count').textContent=`${visits.length} observing dates · ${visits.reduce((n,v)=>n+v.observations.length,0)} exposures`;
  q('#cell-prev').disabled=!visits.length||index===0;q('#cell-next').disabled=!visits.length||index===visits.length-1;q('#cell-play').disabled=visits.length<2;
 }
 function draw(){if(!current)return;const frame=original||!q('#cell-background').checked?current.raw:current.clean;
  const display=processDisplay(frame,{quality:original?false:q('#cell-quality').checked,denoise:original?0:Number(q('#cell-noise').value),repair:original?false:q('#cell-repair').checked,wavelength:current.nearest?frame.wavelength:wavelength,tolerance,spectralMask:!original&&q('#cell-band-mask').checked});
  let stretch=sharedStretch([display]);if(!original){const contrast=Number(q('#cell-contrast').value);stretch={...stretch,low:Math.max(stretch.low,display.background-display.sigma*.4),high:stretch.low+(stretch.high-stretch.low)/contrast};}
  drawAligned(canvas,display,stretch);canvas.style.imageRendering=!original&&q('#cell-interpolate').checked?'auto':'pixelated';canvas.hidden=false;message.hidden=true;q('.cell-compass').hidden=false;
  q('#cell-original').setAttribute('aria-pressed',String(original));q('#cell-original').textContent=original?'Back to cleaned':'View original';root.classList.toggle('showing-original',original);
  q('#cell-caption').textContent=`${original?'Original · sky aligned':'Cleaned display'} · ${current.clean.wavelength.toFixed(3)} µm at centre · ${(display.coverage*100).toFixed(0)}% visible${display.repaired?' · '+display.repaired+' estimated pixels':''}`;
 }
 function show(frame,obs,nearest=false){current={...frame,obs,nearest};draw();
  const href=new URL(obs.path,'https://irsa.ipac.caltech.edu');href.searchParams.set('center',p.ra+','+p.dec);href.searchParams.set('size','.3');href.searchParams.set('gzip','false');
  q('#cell-details').innerHTML=`<dl><dt>Observed (UTC)</dt><dd>${escape(obs.date.replace('T',' ').replace('Z',''))}</dd><dt>Centre wavelength</dt><dd>${frame.clean.wavelength.toFixed(4)} µm${nearest?' · nearest available':''}</dd><dt>Release / detector</dt><dd>${escape(obs.collection)} · ${escape(obs.band)}</dd><dt>Measured units</dt><dd>${escape(frame.clean.unit||'Not supplied')}</dd><dt>Exposure</dt><dd class="cell-id">${escape(obs.id)}</dd><dt>Orientation</dt><dd>North up · east left · 12′ wide</dd></dl><a href="${escape(href.href)}" target="_blank" rel="noreferrer">Download original FITS ↗</a>`;
 }
 async function fetchFrame(obs,signal){if(cache.has(obs.path))return cache.get(obs.path);const params=parameters();params.set('image',obs.path);params.set('match','true');const res=await fetch('/api/frame?'+params,{signal});if(res.status===204)return null;if(!res.ok){const error=await res.json();throw Error(error.error||'The exposure could not be retrieved.');}
  const image=parseSpectralImage(await res.arrayBuffer()),clean=alignImage(image,grid,wavelength,tolerance,{showAll:true}),raw=alignImage({...image,zodi:null},grid,wavelength,tolerance,{showAll:true});
  if(!Number.isFinite(clean.wavelength))throw Error('This exposure has no calibrated wavelength at the cell centre.');const frame={clean,raw};cache.set(obs.path,frame);while(cache.size>36)cache.delete(cache.keys().next().value);return frame;
 }
 async function selectVisit(n,{autoplay=false,seek=false}={}){
  if(!autoplay)stop();if(!visits[n])return;frameController?.abort();frameController=new AbortController();const signal=frameController.signal,token=++requestId;index=n;const link=new URL(location.href);link.searchParams.set('date',visits[n].day);history.replaceState({},'',link.pathname+link.search);clearImage();const visit=visits[n];visit.status='loading';renderTimeline();q(`[data-visit="${n}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'});status('Opening '+dateLabel(visit.day),'Checking the exposure’s calibrated wavelength…',true);
  let best=null,failures=0,errorText='';
  for(let i=0;i<visit.observations.length;i++){
   const obs=visit.observations[i];try{const frame=await fetchFrame(obs,signal);if(dead||token!==requestId)return;if(!frame)continue;
    const distance=Math.abs(frame.clean.wavelength-wavelength);if(!best||distance<best.distance)best={frame,obs,distance};
    const display=processDisplay(frame.clean,{wavelength,tolerance,denoise:0});
    if(distance<=tolerance&&display.coverage>.02){visit.status='ready';show(frame,obs);renderTimeline();if(playing)playTimer=setTimeout(()=>index<visits.length-1?selectVisit(index+1,{autoplay:true}):stop(),1600);return;}
   }catch(e){if(signal.aborted||dead||token!==requestId)return;failures++;errorText=e.message;}
   status('Finding a wavelength match',`Checked ${i+1} of ${visit.observations.length} exposures on ${dateLabel(visit.day)}.`,true);
  }
  if(dead||token!==requestId)return;visit.status=failures?'error':'empty';renderTimeline();if(!failures&&(seek||playing)&&n<visits.length-1)return selectVisit(n+1,{autoplay:playing,seek});stop();closest=best;
  status(failures?'Some exposures could not load':'No match in this wavelength window',failures?errorText:`No usable image at ${wavelength.toFixed(3)} ± ${tolerance.toFixed(2)} µm on this date. Try another date or a wider window.`);
  q('#cell-retry').textContent='Retry this date';q('#cell-retry').hidden=!failures;q('#cell-nearest').hidden=!best;if(best)q('#cell-nearest').textContent=`Show nearest · ${best.frame.clean.wavelength.toFixed(3)} µm`;
 }
 async function search(){const preferredDay=new URLSearchParams(location.search).get('date');stop();searchController?.abort();frameController?.abort();requestId++;searchController=new AbortController();const signal=searchController.signal;clearImage();visits=[];renderTimeline();q('#cell-date').textContent='Searching archive';q('#cell-count').textContent='Looking for dated exposures';status('Finding observations…',`Searching SPHEREx DR1 and QR3 near ${wavelength.toFixed(3)} µm.`,true);
  const u=new URL(location.href);u.searchParams.set('channel',channel);history.replaceState({},'',u.pathname+u.search);q('.cell-back').href='/explore/?hpx='+selection.id+'&order=9&channel='+channel;
  try{const r=await fetch('/api/observations?'+parameters(),{signal});const data=await r.json();if(!r.ok)throw Error(data.error||'Archive search failed.');if(dead||signal.aborted)return;visits=groupVisits(data.observations);index=0;renderTimeline();if(!visits.length){status('No observations at this wavelength','Choose another wavelength to search this cell.');return;}const preferred=visits.findIndex(v=>v.day===preferredDay);await selectVisit(preferred>=0?preferred:0,{seek:!preferredDay});
  }catch(e){if(signal.aborted||dead)return;status('The archive is unavailable',e.message);q('#cell-retry').hidden=false;q('#cell-retry').textContent='Retry archive search';}
 }
 q('#cell-dates').addEventListener('click',e=>{const b=e.target.closest('[data-visit]');if(b)selectVisit(Number(b.dataset.visit));});
 q('#cell-prev').onclick=()=>selectVisit(index-1);q('#cell-next').onclick=()=>selectVisit(index+1);q('#cell-play').onclick=()=>{if(playing){stop();return;}playing=true;q('#cell-play').textContent='Pause';selectVisit(index===visits.length-1?0:index+1,{autoplay:true});};
 q('#cell-retry').onclick=()=>visits.length?selectVisit(index):search();q('#cell-nearest').onclick=()=>{if(closest)show(closest.frame,closest.obs,true);};
 q('#cell-original').onclick=()=>{original=!original;draw();};
 for(const id of ['quality','background','noise','interpolate','repair','contrast','band-mask'])q('#cell-'+id).addEventListener('input',draw);
 q('#cell-zoom').oninput=e=>{canvas.style.width=`${Number(e.target.value)*100}%`;canvas.style.height=`${Number(e.target.value)*100}%`;};q('#cell-fit').onclick=()=>{q('#cell-zoom').value=1;canvas.style.width='100%';canvas.style.height='100%';};
 canvas.addEventListener('pointermove',e=>{if(!current)return;const r=canvas.getBoundingClientRect(),side=Math.min(r.width,r.height),ox=(r.width-side)/2,oy=(r.height-side)/2,x=Math.floor((e.clientX-r.left-ox)/side*grid.pixels),y=Math.floor((e.clientY-r.top-oy)/side*grid.pixels);if(x<0||y<0||x>=grid.pixels||y>=grid.pixels)return;const i=y*grid.pixels+x,v=current.raw.values[i],w=current.raw.wavelengths[i];q('#cell-pixel').textContent=`Pixel ${x+1}, ${y+1} · original ${Number.isFinite(v)?v.toPrecision(4):'no data'} ${current.raw.unit} · ${Number.isFinite(w)?w.toFixed(3)+' µm':'uncalibrated'}${current.raw.quality[i]?'':' · flagged'}`;});
 q('#cell-wave').onchange=e=>{channel=Number(e.target.value);wavelength=metadata.wavelengths[channel];search();};q('#cell-tolerance').onchange=e=>{tolerance=Number(e.target.value);search();};
 (async()=>{try{const r=await fetch('/assets/spherex-survey.json');if(!r.ok)throw Error('Wavelength metadata unavailable.');metadata=await r.json();if(dead)return;const requested=Number(new URLSearchParams(location.search).get('channel'));if(new URLSearchParams(location.search).has('channel')&&Number.isInteger(requested)&&requested>=0&&requested<metadata.wavelengths.length&&!metadata.blankFrames.includes(requested))channel=requested;wavelength=metadata.wavelengths[channel];q('#cell-wave').innerHTML=metadata.wavelengths.map((w,i)=>`<option value="${i}" ${i===channel?'selected':''} ${metadata.blankFrames.includes(i)?'disabled':''}>${w.toFixed(3)} µm</option>`).join('');q('#cell-wave').disabled=false;await search();}catch(e){if(!dead)status('Could not start the viewer',e.message);}})();
 return()=>{dead=true;stop();searchController?.abort();frameController?.abort();cache.clear();};
}
